WITH cleaned AS (SELECT id, device_code, reading_ts, temp_c, humidity, status_bits, firmware, CAST(reading_ts AS DATE) AS reading_ts_day, DATE_FORMAT(reading_ts, 'MMM yyyy') AS reading_ts_label FROM device_readings WHERE firmware NOT IN ('1.0.3', '2.0.1')), with_gaps AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) > INTERVAL '30' MINUTE THEN 1 ELSE 0 END AS is_new_session FROM cleaned), islands AS (SELECT id, device_code, reading_ts, humidity, status_bits, firmware, reading_ts_label, SUM(is_new_session) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT device_code, (UNIX_TIMESTAMP(MAX(reading_ts)) - UNIX_TIMESTAMP(MIN(reading_ts))) / 60 AS span_minutes, SUM(CASE WHEN device_code = 'DV-02' THEN status_bits ELSE 0 END) AS dv_02_status_bits FROM islands GROUP BY device_code;
